from pathlib import Path
import json,re
B=Path(__file__).resolve().parents[1];p=B/'source/states.json';s=json.loads(p.read_text());s=[x for x in s if x['group'] not in ['ikonlar','professional']]
keymap={'professional':'eventV1CategoryNetworking','social':'eventV1CategorySocial','activity':'eventV1CategoryActivity','networking':'communityOptionNetworking','friendship':'communityOptionFriendship'}
for name,names,title in [('categories',['professional','social','activity'],'y1Category'),('communities',['networking','friendship'],'communitySettingsTitle')]:
 s.append(dict(id='icons-'+name,group='ikonlar',title=title,blocks=[dict(type='icons',names=names,keys=keymap)],notes='Design-system specimen:16/20/24 visible sizes,48 interaction target. Category Ink; community coloured only with text. Professional bag differs from Networking connected squares.'))
def P(k,**kw):return dict(type='text',key=k,**kw)
def eventrow():return dict(type='row',label={'en':'Open Studio Meetup','tr':'Açık Stüdyo Buluşması'},icon='professional',blocks=[P('eventV1CategoryLabel',params={'category':{'en':'Professional','tr':'Profesyonel'}},helper=True),dict(type='fixture',en='14 Nov 2026 · 14:00',tr='14 Kas 2026 · 14:00',helper=True)])
for mode in ['list','detail','suggest','past','loading','failed','empty']:
 b=[]
 if mode=='list':b=[dict(type='community',community='Networking'),eventrow()]
 elif mode=='detail':b=[dict(type='fixture',en='Open Studio Meetup',tr='Açık Stüdyo Buluşması'),dict(type='row',key='eventV1CategoryNetworking',icon='professional'),P('eventV1CategoryLabel',params={'category':{'en':'Professional','tr':'Profesyonel'}}),dict(type='heading',key='eventV1Venue'),dict(type='fixture',en='The Example Room',tr='Örnek Salon'),dict(type='actions',items=[dict(key='eventV1Interested',action='existing-rsvp'),dict(key='eventV1Going',action='existing-rsvp')],equal=True)]
 elif mode=='suggest':b=[dict(type='choices',key='y1Category',name='event-category',items=[dict(key='y1Category'+x,icon=i,value=x,selected=x=='Networking') for x,i in [('Networking','professional'),('Social','social'),('Activity','activity')]])]
 elif mode=='past':b=[dict(type='row',label={'en':'Open Studio Meetup','tr':'Açık Stüdyo Buluşması'},icon='professional',blocks=[P('eventV1CategoryLabel',params={'category':{'en':'Professional','tr':'Profesyonel'}}),dict(type='fixture',en='12 Sep 2026 · 14:00',tr='12 Eyl 2026 · 14:00')]),P('eventV1Started'),P('eventV1LockedBody',helper=True)]
 elif mode=='loading':b=[dict(type='community',community='Networking'),dict(type='notice',key='eventsV1Loading',busy=True)]
 elif mode=='failed':b=[dict(type='community',community='Networking'),dict(type='notice',key='eventsV1ErrorTitle',error=True),P('eventsV1ErrorBody'),dict(type='actions',items=[dict(key='checkInRetry',to='professional-loading')])]
 else:b=[dict(type='community',community='Networking'),P('eventsV1EmptyTitle'),P('eventsV1EmptyBody')]
 s.append(dict(id='professional-'+mode,group='professional',title='y1Suggest' if mode=='suggest' else 'navEvents',blocks=b,notes='Category label renamed to Professional/Profesyonel; enum and keys preserved. Category is not community. Fictional event/venue for layout; other Events controls remain governed by existing Events spec, no new RSVP behavior.',**({'nav':'Events'} if mode in ['list','loading','failed','empty'] else {})))
p.write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n')
m=Path('v15/source/group-notes.json');z=json.loads(m.read_text());z['ikonlar']={'spec':'5 çizgi işareti: Professional çanta, Social konuşma, Activity yükselen hareket çizgisi, Networking bağlı kareler, Friendship iki kişi. Professional ve Networking farklı geometridir. 16/20/24 SVG, görünür çizgi1.8dp; 24grid. Kategori Ink, topluluk ikon/etiketli control içinde kendi tonu.','handoff':'SVG’ler assets/svg altında; Flutter yerleşik CustomPainter ile aynı path koordinatları çizilebilir, SVG runtime bağımlılığı ekleme. Hedef en az48; görünen simge16/20/24, paddingilehedef. Kategori simgesi decorative; aynı etiket okunur. Topluluk düğmesi a11y label/hint kullanır.','decisions':'★5 ikon yeterli; yeni bir ikon ailesi yok, v2.3round cap/join1.8 devamı. ★Kategoriler renksiz, topluluk ikonu yalnız community yüzeylerinde renkli. YENİ BİLEŞEN — ONAY GEREKİR: yok; talep edilen mevcut çizgi ailesi uzantısı.'};z['professional']={'spec':'eventV1CategoryNetworking ve y1CategoryNetworking değerleri Professional / Profesyonel; anahtar adı ve teldeNETWORKINGenum değişmez. Listede topluluk pillNetworking yukarıda, kartta çanta+Professional; kategori ve topluluk ayrımı açık. Detay ve geçmişte Category: {category} anahtarı; öneri formunda3radyo aynıağırlık.','handoff':'Bu sayfalar kategori/ikon yerleştirme bağlamı örnekleridir; mevcutEventsV1 ayrıntı/RSVP/tarih/iptal akışlarını kaldırmaz. Aynı etiket geçmiş etkinliğe de uygulanır; veri göçü veya kategoriden topluluk çıkarımı yok. Kayıt fixturegerçeketkinlik/konum içermez.','decisions':'★Networking yalnız topluluk, Professional yalnız kategori etiketi olarak birlikte gösterildi; ikonu farklı. YENİ BİLEŞEN — ONAY GEREKİR: yok.'};m.write_text(json.dumps(z,ensure_ascii=False,indent=2)+'\n')
# Export exact path geometries from our existing preview icon dictionary.
text=(B/'preview.js').read_text();chunk=text.split('const paths={',1)[1].split('};\nconst icon',1)[0];out=B/'ikonlar/assets/svg';out.mkdir(parents=True,exist_ok=True)
for name in keymap:
 path=re.search(r"(?:^|,)"+name+r":'([^']+)'",chunk).group(1)
 for size in [16,20,24]:
  svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="#191A17" stroke-width="{1.8*24/size:g}" stroke-linecap="round" stroke-linejoin="round">{path}</svg>\n'
  (out/f'{name}-{size}.svg').write_text(svg)
